import { Injectable, inject, isDevMode } from '@angular/core';
import { AAL_CONFIG } from '../config/aal-config';

/**
 * Dev-mode accessibility assertions (FR-08).
 *
 * The PRD's "impossible to misuse silently" principle (§1.3) needs teeth. Where
 * TypeScript can make a misconfiguration unrepresentable it should — but a
 * great deal cannot be expressed in the type system: whether projected content
 * actually produced an accessible name, whether a role is nested legally,
 * whether two landmarks collide.
 *
 * Those are checked here, at runtime, in development only. Every message names
 * the requirement, states the user impact, and gives the fix — an error that
 * says "invalid ARIA" teaches nobody anything.
 *
 * Production: every method short-circuits on `isDevMode()`, and the whole class
 * is tree-shaken from production bundles because no live call site survives.
 */
@Injectable({ providedIn: 'root' })
export class A11yAssertService {
  private readonly config = inject(AAL_CONFIG);
  private readonly reported = new Set<string>();

  /** Whether assertions run at all. */
  get enabled(): boolean {
    return isDevMode() && this.config.assertions !== 'off';
  }

  /**
   * Report a violation.
   *
   * Deduplicated by message: a broken component inside an `@for` would
   * otherwise throw once per row and bury the real problem in noise.
   */
  fail(requirement: string, message: string, fix: string, docs?: string): void {
    if (!this.enabled) return;

    const key = `${requirement}:${message}`;
    if (this.reported.has(key)) return;
    this.reported.add(key);

    const full =
      `[AAL][${requirement}] ${message}\n` +
      `  Fix: ${fix}` +
      (docs ? `\n  Docs: ${docs}` : '');

    if (this.config.assertions === 'throw') throw new Error(full);
    console.error(full);
  }

  /**
   * An interactive element must expose a non-empty accessible name (AR-01,
   * SC 4.1.2). Unnamed controls are one of the most common real-world failures
   * — WebAIM Million finds unlabelled inputs on roughly half of all pages.
   *
   * Deliberately checks the RENDERED result rather than "did the consumer pass
   * an input": content projection, aria-label and aria-labelledby can all
   * supply the name, and only the computed outcome tells you whether one did.
   */
  assertAccessibleName(el: Element, component: string, docs?: string): void {
    if (!this.enabled) return;
    if (this.computeName(el)) return;

    this.fail(
      'FR-08 / AR-01',
      `<${component}> has no accessible name. A screen-reader user hears only its role — "button", with no indication of what it does.`,
      'Project text content into the component, or pass the ariaLabel input if it is icon-only.',
      docs,
    );
  }

  /** A role's required ARIA properties must be present (SC 4.1.2). */
  assertRequiredAria(el: Element, role: string, required: readonly string[], component: string): void {
    if (!this.enabled) return;

    const missing = required.filter((attr) => !el.hasAttribute(attr));
    if (missing.length === 0) return;

    this.fail(
      'AR-16',
      `<${component}> renders role="${role}" but is missing required ${missing.length === 1 ? 'attribute' : 'attributes'}: ${missing.join(', ')}. Assistive technology cannot report the component's state.`,
      `Add ${missing.join(', ')}. If AAL owns this attribute, this is a library bug — please report it.`,
    );
  }

  /**
   * Consumers may add descriptive ARIA, but never override attributes AAL owns
   * (PRD §7.11 rule 3). An overridden `aria-expanded` desynchronises from the
   * real state the moment the user interacts, and then the component lies.
   */
  assertNoOwnedAriaOverride(el: Element, owned: readonly string[], component: string): void {
    if (!this.enabled) return;

    const overridden = owned.filter((attr) => el.hasAttribute(`data-consumer-${attr}`));
    if (overridden.length === 0) return;

    this.fail(
      'FR-08 / §7.11',
      `<${component}> has consumer overrides for ARIA that AAL owns: ${overridden.join(', ')}. These desynchronise from the component's real state as soon as the user interacts with it.`,
      'Remove the override. Descriptive ARIA (aria-description, aria-keyshortcuts) is fine; state attributes are not.',
    );
  }

  /**
   * Landmarks of the same type need distinct accessible names (SC 1.3.1 /
   * AR-24). Two unnamed `<nav>` elements are announced identically, so a
   * screen-reader user cannot tell the primary navigation from the footer one.
   */
  assertUniqueLandmarkName(doc: Document, role: string, name: string | null): void {
    if (!this.enabled || !name) return;

    const peers = Array.from(doc.querySelectorAll(`[role="${role}"], ${role === 'navigation' ? 'nav' : role}`));
    const clashes = peers.filter((p) => this.computeName(p) === name);
    if (clashes.length <= 1) return;

    this.fail(
      'AR-24',
      `${clashes.length} "${role}" landmarks share the accessible name "${name}". A screen-reader user navigating by landmark hears the same label repeatedly and cannot tell them apart.`,
      `Give each ${role} a distinct name, e.g. "Primary" and "Footer".`,
    );
  }

  /** Minimal accessible-name computation — enough for assertion purposes. */
  private computeName(el: Element): string {
    const labelledBy = el.getAttribute('aria-labelledby');
    if (labelledBy) {
      const text = labelledBy
        .split(/\s+/)
        .map((id) => el.ownerDocument?.getElementById(id)?.textContent?.trim() ?? '')
        .filter(Boolean)
        .join(' ');
      if (text) return text;
    }

    const label = el.getAttribute('aria-label')?.trim();
    if (label) return label;

    // An image's alt text contributes to the name of a control wrapping it.
    const alt = el.querySelector('img[alt]')?.getAttribute('alt')?.trim();
    return this.visibleText(el) || alt || '';
  }

  /**
   * Text content EXCLUDING aria-hidden subtrees.
   *
   * Plain `textContent` was the original implementation and it was wrong in
   * precisely the case this service exists to catch: an icon-only button
   * containing `<span aria-hidden="true">x</span>` has non-empty textContent
   * but a completely empty accessible name. Counting hidden text as a name
   * meant the icon-only assertion silently never fired.
   */
  private visibleText(el: Element): string {
    let text = '';

    for (const node of Array.from(el.childNodes)) {
      if (node.nodeType === 3 /* Node.TEXT_NODE */) {
        text += node.textContent ?? '';
        continue;
      }
      if (!(node instanceof Element)) continue;
      if (node.getAttribute('aria-hidden') === 'true') continue;
      if (node.hasAttribute('hidden')) continue;

      text += this.visibleText(node);
    }

    return text.trim();
  }

  /** Test-only: clear the dedupe cache between cases. */
  resetForTesting(): void {
    this.reported.clear();
  }
}

import { DestroyRef, Injectable, inject } from '@angular/core';
import { LiveAnnouncer } from '@angular/cdk/a11y';
import { AAL_CONFIG } from '../config/aal-config';

export type AalPoliteness = 'polite' | 'assertive';

/**
 * U+200B. Built from its code point rather than typed literally: an invisible
 * character in source is unreviewable, and ESLint's no-irregular-whitespace
 * rule rightly rejects it.
 */
const ZERO_WIDTH_SPACE = String.fromCharCode(0x200b);

/**
 * Screen-reader announcements (AR-14, AR-25 / SC 4.1.3).
 *
 * Wraps CDK's `LiveAnnouncer` rather than reimplementing live regions — CDK
 * already handles the awkward parts (region creation, the clear-then-set dance
 * some screen readers need). What it does not handle is the three failure modes
 * that actually bite in practice, which is why this facade exists:
 *
 *   1. **Flooding.** A live region updated on every keystroke produces a
 *      stutter of half-spoken phrases and the user hears nothing useful.
 *      Debounced (configurable, 150ms default).
 *   2. **Duplicate suppression.** Screen readers ignore a live region set to
 *      the text it already contains, so a repeated identical message is
 *      silently dropped. Re-announced with a zero-width space appended so it
 *      registers as a change while sounding identical.
 *   3. **Assertive overuse.** `assertive` interrupts whatever the user is
 *      currently reading. It is correct for errors and almost nothing else.
 *      Kept as a separate, deliberate method rather than a parameter.
 */
@Injectable({ providedIn: 'root' })
export class AalLiveAnnouncer {
  private readonly cdk = inject(LiveAnnouncer);
  private readonly config = inject(AAL_CONFIG);

  private pending: ReturnType<typeof setTimeout> | null = null;
  private lastMessage = '';

  constructor() {
    inject(DestroyRef).onDestroy(() => this.cancel());
  }

  /**
   * Announce without interrupting. The default, and correct for almost
   * everything: selection changes, filter results, loading completion.
   */
  polite(message: string): void {
    this.schedule(message, 'polite');
  }

  /**
   * Announce immediately, interrupting current speech.
   *
   * Reserve for content the user must hear before continuing — validation
   * errors on submit, session expiry. Overusing this makes a screen reader
   * unusable, because the user is cut off mid-sentence every time anything
   * changes.
   */
  assertive(message: string): void {
    this.schedule(message, 'assertive');
  }

  /** Clear the live region and drop any pending announcement. */
  clear(): void {
    this.cancel();
    this.lastMessage = '';
    this.cdk.clear();
  }

  private schedule(message: string, politeness: AalPoliteness): void {
    const text = message.trim();
    if (!text) return;

    this.cancel();

    const emit = () => {
      // Screen readers skip a live region set to the text it already holds.
      // A zero-width space makes it a change without changing what is spoken.
      const payload = text === this.lastMessage ? text + ZERO_WIDTH_SPACE : text;
      this.lastMessage = text;
      this.cdk.announce(payload, politeness);
      this.pending = null;
    };

    // Errors are not debounced — delaying an interruption defeats the point.
    if (politeness === 'assertive' || this.config.announceDebounceMs <= 0) {
      emit();
      return;
    }

    this.pending = setTimeout(emit, this.config.announceDebounceMs);
  }

  private cancel(): void {
    if (this.pending === null) return;
    clearTimeout(this.pending);
    this.pending = null;
  }
}

import { Injectable } from '@angular/core';

/**
 * Deterministic, collision-free element IDs for ARIA relationships (FR-07).
 *
 * Every `aria-labelledby`, `aria-describedby`, `aria-controls` and
 * `aria-activedescendant` in AAL resolves through here. Hand-rolled IDs are
 * banned (CLAUDE.md) for two reasons:
 *
 *   1. Two instances of the same component on one page would emit duplicate
 *      IDs, and a duplicate ID silently repoints an ARIA relationship at the
 *      wrong element — a defect that renders correctly and reads wrongly.
 *   2. SSR (FR-09). Server and client must generate identical IDs or hydration
 *      mismatches, and the relationship breaks after hydration only. Because
 *      this service is `providedIn: 'root'`, the server creates a fresh
 *      instance per request and the counter restarts from the same point on
 *      both sides.
 */
@Injectable({ providedIn: 'root' })
export class AriaIdService {
  private counter = 0;

  /**
   * Next unique ID for `prefix`.
   *
   * @example ids.next('aal-dialog-title') // 'aal-dialog-title-0'
   */
  next(prefix: string): string {
    return `${prefix}-${this.counter++}`;
  }

  /** Reset the counter. Test-only; calling it in application code will cause collisions. */
  reset(): void {
    this.counter = 0;
  }
}

import { DOCUMENT, Injectable, inject } from '@angular/core';

export type DismissReason = 'escape' | 'outside-pointer' | 'focus-loss' | 'programmatic';

export interface DismissLayerOptions {
  readonly onDismiss: (reason: DismissReason) => void;
  /** Default true. SC 2.1.2 requires an Escape route out of a modal layer. */
  readonly escape?: boolean;
  /** Default true. Tooltips set false — they dismiss on Escape and blur only. */
  readonly outsidePointer?: boolean;
}

export interface DismissLayerRef {
  /** Dismiss this layer and remove it from the stack. */
  dismiss(reason?: DismissReason): void;
  /** True when this layer is the top-most one, and therefore what Escape targets. */
  isTop(): boolean;
}

/**
 * A dismiss-layer stack for overlays (AR-15, AR-21).
 *
 * Every overlay pushes a layer; Escape dismisses ONLY the top-most one. That
 * is what SC 2.1.2 requires, and it is precisely what naive implementations
 * get wrong: attach an Escape handler per component, then open a confirmation
 * dialog from inside a dialog, and one Escape closes both. The user loses
 * their work with no idea why.
 *
 * No component can know what is stacked above it, so a single shared stack
 * with one document-level listener is the only way to get this right.
 */
@Injectable({ providedIn: 'root' })
export class DismissService {
  private readonly doc = inject(DOCUMENT);

  private readonly layers: { element: HTMLElement; options: DismissLayerOptions }[] = [];
  private listening = false;

  /** Number of currently open layers. */
  get depth(): number {
    return this.layers.length;
  }

  /** Push a layer onto the stack. */
  register(element: HTMLElement, options: DismissLayerOptions): DismissLayerRef {
    const layer = { element, options };
    this.layers.push(layer);
    this.startListening();

    return {
      dismiss: (reason: DismissReason = 'programmatic') => {
        const i = this.layers.indexOf(layer);
        if (i === -1) return; // already dismissed
        this.layers.splice(i, 1);
        if (this.layers.length === 0) this.stopListening();
        options.onDismiss(reason);
      },
      isTop: () => this.layers.at(-1) === layer,
    };
  }

  private startListening(): void {
    if (this.listening) return;
    this.listening = true;
    // Capture phase: the stack must see Escape before content inside a layer
    // can stopPropagation and strand the user with no way out.
    this.doc.addEventListener('keydown', this.onKeydown, true);
    this.doc.addEventListener('pointerdown', this.onPointerDown, true);
  }

  private stopListening(): void {
    if (!this.listening) return;
    this.listening = false;
    this.doc.removeEventListener('keydown', this.onKeydown, true);
    this.doc.removeEventListener('pointerdown', this.onPointerDown, true);
  }

  private readonly onKeydown = (event: Event): void => {
    const e = event as KeyboardEvent;
    if (e.key !== 'Escape') return;

    const top = this.layers.at(-1);
    if (!top || top.options.escape === false) return;

    e.preventDefault();
    e.stopPropagation();
    this.pop('escape');
  };

  private readonly onPointerDown = (event: Event): void => {
    const top = this.layers.at(-1);
    if (!top || top.options.outsidePointer === false) return;

    const target = event.target as Node | null;
    if (target && top.element.contains(target)) return;

    this.pop('outside-pointer');
  };

  private pop(reason: DismissReason): void {
    const top = this.layers.pop();
    if (!top) return;
    if (this.layers.length === 0) this.stopListening();
    top.options.onDismiss(reason);
  }

  /** Test-only: clear the stack and detach listeners. */
  resetForTesting(): void {
    this.layers.length = 0;
    this.stopListening();
  }
}

import { DOCUMENT, Injectable, inject } from '@angular/core';

export interface ObscuringResult {
  /** True when no part of the element's focus perimeter is covered. */
  readonly visible: boolean;
  /** The element doing the covering, when one was found. */
  readonly obscuredBy: Element | null;
  /** Fraction of the element's area that is covered, 0–1. */
  readonly coverage: number;
}

/**
 * SC 2.4.11 Focus Not Obscured (Minimum), Level AA — AR-06.
 *
 * When an element receives focus, no part of it may be *entirely* hidden by
 * author-created content. The everyday failure is mundane and extremely
 * common: a sticky header or a cookie bar overlays the element the user just
 * tabbed to, so the focus ring is painted underneath it and a keyboard user
 * has no idea where they are.
 *
 * This is new in WCAG 2.2 and, per PRD §9, no mainstream component library
 * enforces it — which makes it one of the more defensible novelty claims in
 * this project. Enforcing it is only possible from a service like this: it
 * depends on what the *consumer* stacked above the component, so no amount of
 * care inside a component can guarantee it.
 *
 * Deliberately measures geometry rather than trusting z-index. Stacking
 * contexts, transforms and `position: fixed` interact in ways that make
 * z-index a poor proxy for "is this actually on top", and `elementFromPoint`
 * asks the browser the question directly.
 */
@Injectable({ providedIn: 'root' })
export class FocusObscuringGuard {
  private readonly doc = inject(DOCUMENT);

  /**
   * Is `el` visible where it sits, or is something covering it?
   *
   * Samples the element's corners and centre. Sampling rather than exact
   * geometry is a deliberate trade: it is O(1), runs on every focus change
   * without cost, and catches the real-world cases (a bar across the top, a
   * panel down one side). A pathological cover that leaves exactly the sample
   * points clear would be missed, which is an acceptable false-negative rate
   * for something that has to run synchronously on focus.
   */
  check(el: Element): ObscuringResult {
    const win = this.doc.defaultView;
    if (!win || typeof this.doc.elementFromPoint !== 'function') {
      // SSR, or jsdom, which has no layout engine. Report visible rather than
      // inventing a failure — the real check happens in the Playwright suite.
      return { visible: true, obscuredBy: null, coverage: 0 };
    }

    const rect = el.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) {
      return { visible: true, obscuredBy: null, coverage: 0 };
    }

    // Inset by 1px so a sample never lands on a neighbouring element's edge.
    const points = this.samplePoints(rect);

    let covered = 0;
    let coveringElement: Element | null = null;

    for (const [x, y] of points) {
      const topmost = this.coveringElementAt(x, y, el, win);
      if (!topmost) continue;
      covered++;
      coveringElement ??= topmost;
    }

    const coverage = covered / points.length;
    return {
      // SC 2.4.11 (Minimum) is violated only when the element is ENTIRELY
      // hidden. Partial occlusion is 2.4.12 (Enhanced, AAA) and is out of
      // scope for the AA target — so the threshold is every sample covered.
      visible: coverage < 1,
      obscuredBy: coveringElement,
      coverage,
    };
  }

  /** Corners plus centre, inset by 1px so a sample never lands on a neighbour's edge. */
  private samplePoints(rect: DOMRect): [number, number][] {
    const inset = 1;
    return [
      [rect.left + inset, rect.top + inset],
      [rect.right - inset, rect.top + inset],
      [rect.left + inset, rect.bottom - inset],
      [rect.right - inset, rect.bottom - inset],
      [rect.left + rect.width / 2, rect.top + rect.height / 2],
    ];
  }

  /** The element covering `el` at this point, or null if `el` itself is on top. */
  private coveringElementAt(x: number, y: number, el: Element, win: Window): Element | null {
    // Off-screen points are a scroll problem, not an obscuring problem.
    if (x < 0 || y < 0 || x > win.innerWidth || y > win.innerHeight) return null;

    const topmost = this.doc.elementFromPoint(x, y);
    if (!topmost) return null;
    if (topmost === el || el.contains(topmost) || topmost.contains(el)) return null;

    return topmost;
  }

  /**
   * Ensure `el` is not fully obscured, scrolling it clear if it is.
   *
   * Returns true if it was already visible, false if remediation was needed —
   * the caller can log that, because needing to scroll on every focus is a
   * sign the layout has a sticky-header problem worth fixing at source.
   */
  ensureVisible(el: Element): boolean {
    const before = this.check(el);
    if (before.visible) return true;

    // `center` rather than `nearest`: nearest frequently parks the element
    // directly under the very sticky header that was covering it.
    el.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'instant' as ScrollBehavior });
    return false;
  }
}

