import { Injectable, Signal, computed, inject } from '@angular/core';
import { InputModalityDetector } from '@angular/cdk/a11y';
import { AAL_CONFIG } from '../config/aal-config';

export type AalInputModality = 'keyboard' | 'mouse' | 'touch' | null;

/**
 * When the focus ring should be painted (AR-05 / SC 2.4.7).
 *
 * `:focus-visible` handles this natively and is what AAL's CSS uses. This
 * service exists for the cases CSS cannot reach: a component that must know
 * the modality to decide behaviour, not just appearance — for example a menu
 * that should open focused on its first item for a keyboard user but not for a
 * mouse user.
 *
 * Wraps CDK's `InputModalityDetector`, which already deals with the messy part:
 * screen readers fire synthetic mouse events, so naive "was the last event a
 * click" logic misclassifies a screen-reader user as a mouse user and hides the
 * focus ring from exactly the person who needs it.
 *
 * There is deliberately no way to switch the ring off. `focusRing: 'always'`
 * exists; `'never'` does not (see AalConfig).
 */
@Injectable({ providedIn: 'root' })
export class FocusRingPolicy {
  private readonly detector = inject(InputModalityDetector);
  private readonly config = inject(AAL_CONFIG);

  /** Most recent input modality, or null before any input. */
  get modality(): AalInputModality {
    return this.detector.mostRecentModality;
  }

  /** True when a focus ring should currently be painted. */
  readonly shouldShowRing: Signal<boolean> = computed(() => {
    if (this.config.focusRing === 'always') return true;
    return this.detector.mostRecentModality !== 'mouse';
  });

  /**
   * Should focus be moved programmatically for this interaction?
   *
   * Moving focus on a mouse click is usually wrong — the user is already
   * looking where they clicked and a focus jump can scroll the page out from
   * under them. Moving it for a keyboard user is usually right.
   */
  shouldMoveFocus(): boolean {
    return this.detector.mostRecentModality !== 'mouse';
  }
}

import { DOCUMENT, Injectable, inject } from '@angular/core';
import { ConfigurableFocusTrapFactory } from '@angular/cdk/a11y';
import { FocusObscuringGuard } from './focus-obscuring-guard';

/** Elements that can hold focus. Ordered by DOM position at query time. */
const FOCUSABLE_SELECTOR = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'summary',
  '[tabindex]:not([tabindex="-1"])',
].join(', ');

export interface TrapOptions {
  /**
   * Where focus goes when the trap opens. Resolution order is
   * `[aalFocusInitial]` → first tabbable → the container itself.
   * Never a destructive action (PRD §9.5).
   */
  readonly initialFocus?: HTMLElement | null;
  /** Element to restore focus to on release. Defaults to whatever had focus. */
  readonly restoreTo?: HTMLElement | null;
  /** Mark background content inert. Default true; false only for non-modal layers. */
  readonly inertBackground?: boolean;
}

export interface TrapHandle {
  /** Release the trap, restore focus, and un-inert the background. */
  release(): void;
  /** Re-scan for tabbables after the trap's content changes. */
  refresh(): void;
}

/**
 * Modal focus trapping (AR-15 / SC 2.1.2, 2.4.3).
 *
 * Wraps CDK's `ConfigurableFocusTrapFactory` — the trapping itself is solved
 * and reimplementing it would be exactly the duplication PRD §6.3.1 warns
 * against. What CDK does not do, and what actually causes real dialogs to fail
 * accessibility review, is handled here:
 *
 *   1. **`inert` on background content.** A focus trap stops Tab escaping, but
 *      without `inert` a screen reader in browse mode still reads the page
 *      behind the dialog. The user hears content they cannot reach. `inert`
 *      removes it from the accessibility tree entirely, which is what
 *      `aria-modal` promises but does not by itself deliver.
 *   2. **Focus restoration that cannot lose focus.** If the trigger was removed
 *      while the dialog was open — deleted a row, then closed the confirm —
 *      naive restoration sends focus to `<body>` and the keyboard user is
 *      dumped at the top of the document with no idea where they are. This
 *      falls back deliberately.
 *   3. **Obscuring.** The restored element may sit under a sticky header
 *      (SC 2.4.11), so restoration runs through FocusObscuringGuard.
 */
@Injectable({ providedIn: 'root' })
export class FocusTrapFacade {
  private readonly doc = inject(DOCUMENT);
  private readonly factory = inject(ConfigurableFocusTrapFactory);
  private readonly obscuring = inject(FocusObscuringGuard);

  trap(container: HTMLElement, options: TrapOptions = {}): TrapHandle {
    const restoreTo =
      options.restoreTo ?? (this.doc.activeElement instanceof HTMLElement ? this.doc.activeElement : null);

    const trap = this.factory.create(container);
    const uninert = options.inertBackground === false ? () => undefined : this.inertBackground(container);

    this.moveInitialFocus(container, options.initialFocus ?? null);

    return {
      refresh: () => {
        // CDK caches nothing, but re-anchoring keeps the boundary sentinels at
        // the true edges after dynamic content is added.
        trap.destroy();
      },
      release: () => {
        uninert();
        trap.destroy();
        this.restoreFocus(restoreTo);
      },
    };
  }

  /**
   * Resolution order per PRD §9.5. The container fallback carries
   * `tabindex="-1"` so it can hold focus without becoming a tab stop.
   */
  private moveInitialFocus(container: HTMLElement, requested: HTMLElement | null): void {
    const marked = container.querySelector<HTMLElement>('[aalFocusInitial], [data-aal-focus-initial]');
    const tabbable = Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));

    for (const candidate of [requested, marked, ...tabbable]) {
      if (this.tryFocus(candidate)) return;
    }

    // Nothing inside could take focus. The container holds it instead, with
    // tabindex="-1" so it can be focused without becoming a tab stop.
    if (!container.hasAttribute('tabindex')) container.setAttribute('tabindex', '-1');
    container.focus();
  }

  /**
   * Attempt to focus, then VERIFY it landed.
   *
   * Deliberately not `InteractivityChecker.isFocusable()` first. That predicts
   * focusability from layout — correct in a browser, but it returns false for
   * everything in jsdom, where elements have no rendered dimensions. Predicting
   * and then trusting the prediction meant the fallback path fired spuriously
   * in tests and would have masked real regressions.
   *
   * Asking the DOM what actually happened is both simpler and true in every
   * environment: if the element could not take focus, activeElement will not
   * be it, and we move on to the next candidate.
   */
  private tryFocus(el: HTMLElement | null): boolean {
    if (!el || !el.isConnected) return false;
    if (el.hasAttribute('disabled') || el.getAttribute('aria-disabled') === 'true') return false;
    if (el.closest('[inert]')) return false;

    el.focus();
    return el.ownerDocument.activeElement === el;
  }

  /**
   * Mark everything outside `container` inert, walking up from the container
   * and inerting siblings at each level. Returns a function that restores
   * exactly what was changed — elements already inert are left alone, so a
   * nested dialog closing does not un-inert the page for its parent.
   */
  private inertBackground(container: HTMLElement): () => void {
    const changed: HTMLElement[] = [];

    for (let node: HTMLElement | null = container; node && node !== this.doc.body; node = node.parentElement) {
      for (const sibling of Array.from(node.parentElement?.children ?? [])) {
        if (sibling === node || !this.shouldInert(sibling)) continue;
        sibling.setAttribute('inert', '');
        changed.push(sibling);
      }
    }

    return () => changed.forEach((el) => el.removeAttribute('inert'));
  }

  /**
   * Already-inert elements are skipped, so a nested dialog closing does not
   * un-inert the page for the dialog still open behind it. Live regions are
   * skipped because announcements must keep working while a dialog is open.
   */
  private shouldInert(node: Element): node is HTMLElement {
    if (!(node instanceof HTMLElement)) return false;
    if (node.hasAttribute('inert')) return false;
    return !node.hasAttribute('aria-live') && !node.querySelector('[aria-live]');
  }

  /**
   * Restore focus, with a documented fallback chain so focus can never be lost
   * to `<body>` — which for a keyboard user means silently losing their place.
   */
  private restoreFocus(target: HTMLElement | null): void {
    if (this.tryFocus(target)) {
      // The trigger may sit under a sticky header now that the overlay has
      // gone — restoring focus somewhere invisible is its own SC 2.4.11 failure.
      this.obscuring.ensureVisible(target!);
      return;
    }

    // The trigger is gone — a deleted row, a closed panel. Focus must land
    // somewhere meaningful: dropping it on <body> leaves a keyboard user at the
    // top of the document with no idea what happened.
    const fallback =
      this.doc.querySelector<HTMLElement>('main') ??
      this.doc.querySelector<HTMLElement>('h1') ??
      this.doc.body;

    if (!fallback) return;
    if (!fallback.hasAttribute('tabindex')) fallback.setAttribute('tabindex', '-1');
    fallback.focus();
  }
}

import { DOCUMENT, Injectable, Signal, inject, signal } from '@angular/core';

/**
 * Tracks Windows Contrast Themes / `forced-colors: active` (AR-19).
 *
 * Most components need no TypeScript for this — the token layer already swaps
 * to system colour keywords in CSS (`libs/tokens/src/styles/tokens.css`).
 * This exists for the cases CSS cannot express: an icon drawn on canvas, a
 * decorative element that must be hidden, or a shadow-only affordance that has
 * to grow a real border because shadows are not painted in forced-colors mode.
 *
 * Prefer the CSS layer. Reach for this only when the CSS layer genuinely
 * cannot do it.
 */
@Injectable({ providedIn: 'root' })
export class ForcedColorsService {
  private readonly doc = inject(DOCUMENT);
  private readonly state = signal(false);

  readonly forcedColors: Signal<boolean> = this.state.asReadonly();

  constructor() {
    const win = this.doc.defaultView;
    if (!win?.matchMedia) return;

    const query = win.matchMedia('(forced-colors: active)');
    this.state.set(query.matches);
    query.addEventListener('change', (e) => this.state.set(e.matches));
  }
}

import { DOCUMENT, Injectable, Signal, computed, inject, signal } from '@angular/core';

/**
 * Tracks `prefers-reduced-motion` (AR-20 / SC 2.3.1).
 *
 * Exposed as a signal so components gate animation declaratively rather than
 * each re-implementing a matchMedia listener — and so the preference is
 * honoured when the user changes it mid-session, not only at load.
 *
 * SSR-safe: `matchMedia` does not exist on the server, so the server assumes
 * reduced motion. That is the safe default — rendering without animation and
 * then enabling it after hydration is harmless, whereas the reverse would play
 * an animation at a user who asked for none.
 */
@Injectable({ providedIn: 'root' })
export class ReducedMotionService {
  private readonly doc = inject(DOCUMENT);
  private readonly state = signal(true);

  readonly prefersReducedMotion: Signal<boolean> = this.state.asReadonly();
  /** Convenience inverse, for `[class.animated]` style bindings. */
  readonly motionAllowed: Signal<boolean> = computed(() => !this.state());

  constructor() {
    const win = this.doc.defaultView;
    if (!win?.matchMedia) return; // server, or a very old browser

    const query = win.matchMedia('(prefers-reduced-motion: reduce)');
    this.state.set(query.matches);
    query.addEventListener('change', (e) => this.state.set(e.matches));
  }
}

import { DOCUMENT, Injectable, inject } from '@angular/core';

/**
 * Scroll containment for modal layers (AR-15).
 *
 * Two things most implementations get wrong, both of which this handles:
 *
 *   1. **Layout shift.** Setting `overflow: hidden` removes the scrollbar, the
 *      page widens by its width, and everything jumps sideways. Disorienting
 *      for everyone and actively harmful for users with vestibular or
 *      attention-related conditions. Compensated with padding.
 *   2. **Scroll position.** Naive implementations restore to the top on close,
 *      which for a keyboard user means losing their place entirely after
 *      dismissing a dialog.
 *
 * Reference-counted, because nested dialogs must not unlock the page when only
 * the inner one closes.
 */
@Injectable({ providedIn: 'root' })
export class ScrollLockService {
  private readonly doc = inject(DOCUMENT);

  private depth = 0;
  private saved: { overflow: string; paddingInlineEnd: string; scrollY: number } | null = null;

  /** Whether the page is currently locked. */
  get locked(): boolean {
    return this.depth > 0;
  }

  lock(): void {
    if (this.depth++ > 0) return; // already locked by an outer layer

    const win = this.doc.defaultView;
    const body = this.doc.body;
    if (!win || !body) return;

    const style = win.getComputedStyle(body);
    this.saved = {
      overflow: body.style.overflow,
      paddingInlineEnd: body.style.paddingInlineEnd,
      scrollY: win.scrollY,
    };

    // Width of the scrollbar we are about to remove.
    const gap = win.innerWidth - this.doc.documentElement.clientWidth;

    body.style.overflow = 'hidden';
    if (gap > 0) {
      const existing = parseFloat(style.paddingInlineEnd) || 0;
      body.style.paddingInlineEnd = `${existing + gap}px`;
    }
  }

  unlock(): void {
    if (this.depth === 0) return;
    if (--this.depth > 0) return; // an outer layer still holds the lock

    const win = this.doc.defaultView;
    const body = this.doc.body;
    if (!win || !body || !this.saved) return;

    body.style.overflow = this.saved.overflow;
    body.style.paddingInlineEnd = this.saved.paddingInlineEnd;
    win.scrollTo({ top: this.saved.scrollY, behavior: 'instant' as ScrollBehavior });
    this.saved = null;
  }

  /** Test-only: drop all locks. */
  resetForTesting(): void {
    this.depth = 0;
    this.saved = null;
  }
}

import { Injectable } from '@angular/core';

/**
 * APG printable-character typeahead (AR-03).
 *
 * Used by Listbox, Menu, Tabs and the grid: type "de" and land on "Denmark".
 * Shared rather than reimplemented per component so the reset window and
 * matching rules cannot drift — inconsistent typeahead between two widgets in
 * the same app is a usability defect a screen-reader user notices immediately.
 *
 * Behaviour follows the APG:
 *   - buffer resets after ~500ms of inactivity
 *   - matching is case-insensitive, from the start of the label
 *   - the SAME character repeated cycles through items starting with it, which
 *     is how a user reaches the third "Sales…" entry without typing it out
 *   - search wraps, starting after the currently-active item
 */
@Injectable({ providedIn: 'root' })
export class TypeaheadService {
  /** APG-conventional reset window. */
  static readonly RESET_MS = 500;

  private buffer = '';
  private lastKeyAt = 0;

  /**
   * Feed a keystroke and get the index to move to, or null for no match.
   *
   * @param char       the printable character typed
   * @param labels     item labels, in DOM order
   * @param activeIndex currently active index, or -1
   * @param now        injectable clock, for deterministic tests
   */
  type(char: string, labels: readonly string[], activeIndex: number, now = Date.now()): number | null {
    if (!this.isPrintable(char)) return null;

    if (now - this.lastKeyAt > TypeaheadService.RESET_MS) this.buffer = '';
    this.lastKeyAt = now;
    this.buffer += char.toLowerCase();

    const { needle, start } = this.searchFrom(activeIndex);

    for (let i = 0; i < labels.length; i++) {
      const index = (start + i + labels.length) % labels.length;
      if (labels[index]?.trim().toLowerCase().startsWith(needle)) return index;
    }

    return null;
  }

  /**
   * What to search for, and where to start searching from.
   *
   * Repeating a single character cycles through items beginning with it rather
   * than searching for "aaa" — APG behaviour, and how a user reaches the third
   * "Sales…" entry without typing the whole label. A cycling search, or the
   * first keystroke of a new one, starts AFTER the active item so that
   * repeated presses advance instead of re-matching the current item.
   */
  private searchFrom(activeIndex: number): { needle: string; start: number } {
    const isRepeat = this.buffer.length > 1 && new Set(this.buffer).size === 1;
    return {
      needle: isRepeat ? this.buffer[0] : this.buffer,
      start: isRepeat || this.buffer.length === 1 ? activeIndex + 1 : activeIndex,
    };
  }

  /** Clear the buffer — call when the widget closes or loses focus. */
  reset(): void {
    this.buffer = '';
    this.lastKeyAt = 0;
  }

  /** Current buffer, for tests and debugging. */
  get current(): string {
    return this.buffer;
  }

  /**
   * A single printable character. Excludes named keys ("Enter", "ArrowDown")
   * and, deliberately, the space character: Space activates the focused item in
   * most APG patterns, so consuming it for typeahead would break activation.
   */
  private isPrintable(char: string): boolean {
    return char.length === 1 && char !== ' ' && !/^\s$/.test(char);
  }
}

